const chapterNames = {
  C1: 'Chương 1 · Mạng máy tính và Internet',
  C2: 'Chương 2 · Tầng Application',
  C3: 'Chương 3 · Tầng Transport',
  C4: 'Chương 4 · Tầng Network'
};

const shuffleWithSeed = (items, seed) => {
  const arr = [...items];
  let x = seed >>> 0;
  for (let i = arr.length - 1; i > 0; i--) {
    x = (1664525 * x + 1013904223) >>> 0;
    const j = x % (i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
};

const promptVariants = (item, variant, chapter) => {
  const context = chapterNames[chapter];
  const prompts = [
    item.q,
    item.scenario,
    `Trong ${context}, phương án nào mô tả đúng nhất về “${item.topic}”?`,
    `Một sinh viên cần ghi nhớ kiến thức nào sau đây về “${item.topic}” trong ${context}?`,
    `Phát biểu nào sau đây chính xác khi nói về “${item.topic}” trong ${context}?`
  ];
  return prompts[variant];
};

const questions = [];
const selectedIndices = {
  C1: Array.from({ length: 30 }, (_, i) => i),
  C2: Array.from({ length: 30 }, (_, i) => i),
  C3: [...Array.from({ length: 26 }, (_, i) => i), 28, 29, 30, 31],
  C4: [0, 1, 2, 3, 4, 6, 7, 10, 12, 16, 19, 20, 21, 23, 27, 28, 29, 30, 31, 35, 36, 37, 38, 39, 40, 41, 42, 45, 46, 47]
};

for (const [chapter, rawItems] of Object.entries(BANK)) {
  const items = selectedIndices[chapter].map((i) => rawItems[i]);
  if (items.length !== 30 || items.some((x) => !x)) throw new Error(`${chapter} cần 30 khái niệm hợp lệ`);
  items.forEach((item, conceptIndex) => {
    const omittedSet = conceptIndex % 6;
    const setIds = [0, 1, 2, 3, 4, 5].filter((id) => id !== omittedSet);
    setIds.forEach((setId, variantIndex) => {
      const opts = shuffleWithSeed([item.a, ...item.wrong], conceptIndex * 31 + setId * 101 + chapter.charCodeAt(1));
      questions.push({
        id: `${chapter}-${String(conceptIndex + 1).padStart(2, '0')}-S${setId + 1}`,
        chapter,
        chapterName: chapterNames[chapter],
        topic: item.topic,
        conceptId: `${chapter}-${conceptIndex + 1}`,
        setId: setId + 1,
        difficulty: conceptIndex % 3 === 0 ? 'Cơ bản' : conceptIndex % 3 === 1 ? 'Trung bình' : 'Vận dụng',
        question: promptVariants(item, variantIndex, chapter),
        options: opts,
        answerIndex: opts.indexOf(item.a),
        explanation: item.explain
      });
    });
  });
}

export { BANK, chapterNames };
export default questions;
